int efd = eventfd(0, EFD_CLOEXEC | EFD_NONBLOCK);

// Error Check
if (efd == -1) { return errno; }

// Flags: EFD_SEMAPHORE (Read always returns 1, not total count)

// Write (Incrementing the counter by N)
uint64_t count_inc = 5;
write(efd, &count_inc, sizeof(uint64_t));

// Read (Retrieves current counter value, resets to 0)
uint64_t accumulated_val;
read(efd, &accumulated_val, sizeof(uint64_t));

// Readiness: efd is ready for EPOLLIN when counter > 0.

close(efd);
